import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { readFile } from 'node:fs/promises'
import { join } from 'node:path'

const [repo] = process.argv.slice(2)
for (const args of [['ci', '--ignore-scripts', '--no-audit', '--no-fund'], ['run', 'check']]) {
  const result = spawnSync('npm', args, { cwd: repo, encoding: 'utf8' })
  if (result.error?.code === 'ENOENT') {
    console.error('Blocked: install npm')
    process.exit(2)
  }
  assert.equal(result.status, 0, result.stdout + result.stderr)
  console.error(`maintained-ts-shop: npm ${args.join(' ')} exited ${result.status}`)
}
const contract = JSON.parse(await readFile(join(repo, '.bstack/project.json'), 'utf8'))
assert.deepEqual(contract.checks.map(check => check.command.args), [['run', 'check']])
for (const source of contract.acceptanceSources) {
  assert.ok((await readFile(join(repo, source.path), 'utf8')).includes(source.pointer))
}
assert.match(await readFile(join(repo, '.bstack/bin/bstack-check.mjs'), 'utf8'), /^\/\/ Generated by scripts\/generate-checker.mjs\. Do not edit\./)
assert.equal(spawnSync('git', ['status', '--porcelain'], { cwd: repo, encoding: 'utf8' }).stdout, '')
